        date_verification,score_priorite,besoin_enfant,besoin_etudiant,
        besoin_locataire,besoin_demandeur_emploi,actif
      ) VALUES (
        r.nom,r.categorie,r.commune,r.zone_couverte,r.organisme,r.type_dispositif,
        r.description_fr,r.description_fr,r.description_kreol,r.demarches_fr,r.demarches_kreol,
        r.lien_officiel,r.lien_officiel,r.source_verification,r.periode_validite,r.statut_verification,
        r.date_verification,r.score_priorite,r.besoin_enfant,r.besoin_etudiant,
        r.besoin_locataire,r.besoin_demandeur_emploi,true
      );
